def intro_collage_jpeg() -> bytes:
    return base64.b64decode(INTRO_COLLAGE_B64)


async def dash_intro_collage(request):
    from aiohttp import web
    if not dash_authed(request):
        return dash_error(web, request, 403)
    return web.Response(body=intro_collage_jpeg(), content_type="image/jpeg",
                        headers={"Cache-Control": "private, max-age=86400"})


async def dash_look_img(request):
    from aiohttp import web
    name = request.match_info.get("name", "")
    if name not in LOOK_IDS and name != "default":
        return dash_error(web, request, 404)
    return web.Response(text=look_svg(name), content_type="image/svg+xml",
                        headers={"Cache-Control": "public, max-age=86400"})


async def dash_csv_out(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    kind = request.match_info.get("kind", "")
    if kind not in ("picks", "leaderboard"):
        return dash_error(web, request, 404)
    return web.Response(text=dashboard_csv(prm["guild"], kind), content_type="text/csv")


async def dash_image(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    kind, arg = request.match_info.get("kind", ""), request.match_info.get("arg")
    if arg is None and kind in DASH_POSTERS:
        arg = (prm["period"] or "season") if kind == "standings" else ""
    elif not ((kind == "card" and arg and _DASH_NUM.fullmatch(arg)) or
              (kind == "receipt" and arg and re.fullmatch(r"\d{1,10}", arg))):
        return dash_error(web, request, 404)
    try:
        png = await dashboard_image(kind, prm["guild"], arg, back=prm["back"] == "1")
    except Exception:
        log.exception("Dashboard image %s failed", kind)
        png = None
    if png is None:
        return web.Response(text="nothing to show", status=404, content_type="text/plain")
    return web.Response(body=png, content_type="image/png", headers={"Cache-Control": "private, max-age=60"})


async def dash_health(request):
    from aiohttp import web
    return web.Response(text="ok", content_type="text/plain")


async def dash_favicon(request):
    from aiohttp import web
    return web.Response(text=DASH_LOGO_SVG, content_type="image/svg+xml",
                        headers={"Cache-Control": "private, max-age=86400"})


def dash_manifest_body() -> str:
    return json.dumps({
        "name": "Pimp's Dashboard", "short_name": "PIMP-BOT",
        "description": "The group's sports picks.",
        "start_url": "/", "scope": "/", "display": "standalone",
        "background_color": "#14003A", "theme_color": "#1a0f33",
        "icons": [
            {"src": "/apple-touch-icon.png", "sizes": "180x180", "type": "image/png"},
            {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"},
        ],
    }, separators=(",", ":"))


async def dash_manifest(request):
    from aiohttp import web
    return web.Response(text=dash_manifest_body(), content_type="application/manifest+json",
                        headers={"Cache-Control": "private, max-age=3600"})


SW_JS = (
    "const CACHE='pb-shell-122';"
    "self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/manifest.webmanifest'])).then(()=>self.skipWaiting()))});"
    "self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});"
    "self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;"
    "const u=new URL(req.url);if(u.origin!==location.origin)return;if(u.pathname.startsWith('/api/')||u.pathname.startsWith('/img/'))return;"
    "e.respondWith(fetch(req).then(r=>{try{const copy=r.clone();caches.open(CACHE).then(c=>c.put(req,copy))}catch(x){}"
    "return r}).catch(()=>caches.match(req)))});"
)


async def dash_sw(request):
    from aiohttp import web
    return web.Response(text=SW_JS, content_type="application/javascript",
                        headers={"Cache-Control": "no-cache", "Service-Worker-Allowed": "/"})


async def dash_touch_icon(request):
    from aiohttp import web
    path = request.path or ""
    size = 180 if "apple" in path else 192 if "192" in path else 512
    try:
        img = brand_logo(size)
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        raw = buf.getvalue()
    except Exception:
        return dash_error(web, request, 404)
    return web.Response(body=raw, content_type="image/png",
                        headers={"Cache-Control": "public, max-age=86400"})


async def dash_logout(request):
    from aiohttp import web
    resp = web.Response(status=303, headers={"Location": "/"})
    resp.del_cookie(DASH_COOKIE, path="/")
    resp.del_cookie(DASH_DEV_COOKIE, path="/")
    resp.del_cookie(DASH_STAFF_COOKIE, path="/")
    resp.del_cookie(DASH_ACCT_COOKIE, path="/")
    return resp


async def dash_not_found(request):
    from aiohttp import web
    return dash_error(web, request, 404)


def dash_app(web):
    """The aiohttp app: every route goes through dash_guard."""
    @web.middleware
    async def guard(request, handler):
        return await dash_guard(request, handler)

    app = web.Application(middlewares=[guard], client_max_size=64 * 1024)
    app.add_routes([web.get("/", dash_index), web.get("/login", dash_index), web.get("/app", dash_index),
                    web.get("/live", dash_index), web.get("/news", dash_index), web.get("/open", dash_index),
                    web.get("/people", dash_index), web.get("/posters", dash_index), web.get("/more", dash_index),
                    web.get("/api/data", dash_api_data), web.get("/api/player.json", dash_api_player),
                    web.get(r"/api/player/{league:[a-z0-9-]{2,28}}/{aid:[0-9]{1,12}}.json", dash_api_player_one),
                    web.get("/health", dash_health), web.get("/img/intro-collage.jpg", dash_intro_collage),
                    web.get(r"/img/look/{name:[a-z]+}.svg", dash_look_img),
                    web.get(r"/img/head/{league:[a-z0-9-]+}/{aid:[0-9]{1,12}}.png", dash_head_img),
                    web.get(r"/img/face/{league:[a-z0-9-]+}/{aid:[0-9]{1,12}}.png", dash_head_img),
                    web.get(r"/api/person/{key:\d+}.json", dash_api_person),
                    web.post("/api/dm.json", dash_api_dm),
                    web.post("/api/bank.json", dash_api_bank),
                    web.get(r"/img/ava/{uid:[0-9]{1,20}}.png", dash_avatar_img),
                    web.get(r"/api/slip/{pid:\d+}.json", dash_api_slip),
                    *dash30_routes(web), web.get("/api/{kind}.csv", dash_csv_out), web.get("/img/{kind}.png", dash_image),
                    web.get("/img/{kind}/{arg}.png", dash_image),                     web.get("/favicon.ico", dash_favicon),
                    web.get("/favicon.svg", dash_favicon),
                    web.get("/manifest.webmanifest", dash_manifest),
                    web.get("/apple-touch-icon.png", dash_touch_icon),
                    web.get("/icon-192.png", dash_touch_icon),
                    web.get("/icon-512.png", dash_touch_icon),
                    web.get("/sw.js", dash_sw),
                    web.post("/api/log.json", dash_api_log),
                    web.get("/logout", dash_logout),
                    web.get("/staff", dash_staff), web.get("/api/staff.json", dash_api_staff),
                    web.post("/api/staff.json", dash_api_staff_post),
                    web.get("/account", dash_account), web.post("/account", dash_account_post),
                    web.post("/login", dash_login_post),
                    web.get("/{tail:.*}", dash_not_found)])
    return app


